(()=>{'use strict';let history=[],imported=[],queue=[],position=-1,auto=true,similar=true,version=0;const recent=$('#recent-grid'),recommend=$('#recommendations');
try{history=JSON.parse(localStorage.getItem('oktawka-history')||'[]');if(!Array.isArray(history))history=[];history=history.filter(t=>t&&typeof t.title==='string'&&typeof t.artist==='string').slice(0,80);imported=JSON.parse(localStorage.getItem('oktawka-imports')||'[]');if(!Array.isArray(imported))imported=[];auto=localStorage.getItem('oktawka-autoplay')!=='false';similar=localStorage.getItem('oktawka-similar')!=='false'}catch{}
const metadata=t=>({id:String(t.catalogId||t.id||''),title:String(t.title||'').slice(0,200),artist:String(t.artist||'').slice(0,120),artistId:Number.isSafeInteger(t.artistId)?t.artistId:undefined,album:String(t.album||''),albumId:Number.isSafeInteger(t.albumId)?t.albumId:undefined,genre:String(t.genre||''),artwork:/^https:\/\//.test(t.artwork||'')?t.artwork:'',playedAt:Date.now()});
const key=t=>(t.title+'|'+t.artist).normalize('NFKC').toLowerCase();
function card(t,attr,i){return `<button class="history-card" ${attr}="${i}">${t.artwork?`<img loading="lazy" src="${escapeHTML(t.artwork)}" alt="">`:'<span class="material-symbols-rounded">music_note</span>'}<b>${escapeHTML(t.title)}</b><small>${escapeHTML(t.artist)}</small></button>`}
function renderHome(){recent.innerHTML=history.slice(0,6).map((t,i)=>card(t,'data-history',i)).join('');recent.querySelectorAll('[data-history]').forEach(b=>b.onclick=()=>playAlbum([history[Number(b.dataset.history)]],0));recommend.innerHTML='';const groups=new Map();for(const t of history){const name=t.genre||(t.artist.startsWith('Local file')?'Your local files':t.artist);if(!groups.has(name))groups.set(name,[]);const list=groups.get(name);if(!list.some(x=>key(x)===key(t)))list.push(t)}const playlists=[...groups].slice(0,3);recommend.innerHTML=playlists.map(([name,rows],i)=>`<button class="history-card" data-mix="${i}"><span class="material-symbols-rounded">queue_music</span><b>${escapeHTML(name==='Your local files'?'Your local rotation':name+' mix')}</b><small>${rows.length} ${rows.length===1?'track':'tracks'} from your history</small></button>`).join('')+(imported.length?`<button class="history-card" id="imported-mix"><span class="material-symbols-rounded">library_music</span><b>Imported playlist</b><small>${imported.length} unique tracks</small></button>`:'');recommend.querySelectorAll('[data-mix]').forEach(b=>b.onclick=()=>playAlbum(playlists[Number(b.dataset.mix)][1],0));if($('#imported-mix'))$('#imported-mix').onclick=()=>playAlbum(imported,0);
 const albums=history.filter(t=>t.albumId).filter((t,i,a)=>a.findIndex(x=>x.albumId===t.albumId)===i).slice(0,3);for(const t of albums){const button=document.createElement('button');button.className='history-card';button.innerHTML=(t.artwork?`<img loading="lazy" src="${escapeHTML(t.artwork)}" alt="">`:'')+`<b>${escapeHTML(t.album||'Revisit this album')}</b><small>Because you played ${escapeHTML(t.artist)}</small>`;button.onclick=async()=>{if(window.OktawkaCatalog){const rows=await window.OktawkaCatalog.request('lookup',{id:String(t.albumId),entity:'album'}).catch(()=>[]);window.OktawkaCatalog.remember(rows.filter(a=>a.collectionType==='Album'));window.monoShowAlbum?.(t.albumId)}};recommend.append(button)}
}
function remember(track){if(!track||track.live)return;const t=metadata(track);history=[t,...history.filter(x=>key(x)!==key(t))].slice(0,80);try{localStorage.setItem('oktawka-history',JSON.stringify(history))}catch{}renderHome()}
function replay(t){window.monoCancelCatalogPlayback?.();const local=tracks.findIndex(x=>key(x)===key(t));if(local>=0)return play(local,true);if(t.id||t.album||t.artistId)return window.monoPlayCatalogTrack?.(t);toast('Reimport this local file to play it on this device.')}
function playAlbum(items,start=0){version++;queue=items.filter(t=>t&&t.title&&t.artist).slice(0,20000);position=start;if(queue[position])replay(queue[position])}
function nextInQueue(dir=1){if(!queue.length)return false;const candidate=dir>0&&typeof shuffle!=='undefined'&&shuffle&&queue.length>1?(position+1+Math.floor(Math.random()*(queue.length-1)))%queue.length:position+dir;if(candidate>=0&&candidate<queue.length){version++;position=candidate;replay(queue[position]);return true}if(dir<0)return false;if(similar){extend();return true}return false}
async function extend(){const mine=++version,seed=queue[position]||history[0];if(!seed)return;toast('Finding related artists…');try{const sameGenre=history.filter(t=>t.genre&&t.genre===seed.genre&&t.artist!==seed.artist&&!queue.some(q=>key(q)===key(t)));const response=await fetch('/api/related?artist='+encodeURIComponent(seed.artist));const data=await response.json();if(mine!==version)return;const candidates=[...sameGenre,...(response.ok&&Array.isArray(data.tracks)?data.tracks:[])].filter(t=>t.artist!==seed.artist&&!queue.some(q=>key(q)===key(t)));if(!candidates.length)return toast(data.error||'No related tracks available. Your queue has finished.');queue.push(...candidates.slice(0,12));position++;replay(queue[position])}catch{if(mine===version)toast('Related tracks could not load. Your queue has finished.')}}
function ended(){if(!queue.length)return false;if(auto)nextInQueue(1);return true}
function options(){modal(`<div class="eyebrow">KEEP THE MUSIC GOING</div><h2>Your listening flow.</h2><label class="row"><span>Continue through the album queue</span><input id="flow-auto" type="checkbox"></label><label class="row"><span>Continue with related artists after the queue</span><input id="flow-similar" type="checkbox"></label><p class="note">Related artists use catalog metadata plus other artists in the same genre from your local history. Availability still depends on a playable source.</p><button class="primary" id="flow-save">Save</button>`);$('#flow-auto').checked=auto;$('#flow-similar').checked=similar;$('#flow-save').onclick=()=>{auto=$('#flow-auto').checked;similar=$('#flow-similar').checked;try{localStorage.setItem('oktawka-autoplay',String(auto));localStorage.setItem('oktawka-similar',String(similar))}catch{}$('#dialog').close()}}
function importDialog(){modal(`<div class="eyebrow">PICK · IMPORT · ONE LIBRARY</div><h2>Bring your playlists.</h2><p class="import-copy">Import a CSV or JSON track list exported from your music service. Oktawka removes duplicate artist/title pairs and stores the metadata on this device. Importing a playlist does not grant access to its audio.</p><button id="pick-playlist" class="primary">Choose CSV or JSON</button><p class="note">CSV columns: title, artist, album, genre. JSON: an array of objects with the same fields. Spotify and Apple account sign-in need registered developer credentials and are not connected here. Automatic account sync is not enabled.</p><p id="import-summary" role="status"></p>`);$('#pick-playlist').onclick=()=>$('#playlist-file').click()}
function csv(text){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++}else quoted=!quoted}else if(c===','&&!quoted){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(Boolean))rows.push(row);row=[];cell=''}else cell+=c}row.push(cell);if(row.some(Boolean))rows.push(row);if(quoted)throw Error('Unclosed CSV quote.');const header=rows.shift()?.map(h=>h.trim().toLowerCase())||[];return rows.map(r=>Object.fromEntries(header.map((h,i)=>[h,r[i]||''])))}
$('#playlist-file').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>2*1024*1024)throw Error('Use a playlist smaller than 2 MB.');const text=await file.text();const rows=file.name.toLowerCase().endsWith('.json')?JSON.parse(text):csv(text);if(!Array.isArray(rows))throw Error('Use an array of track objects.');const normalized=rows.filter(r=>r&&typeof(r.title||r['track name'])==='string'&&typeof(r.artist||r['artist name'])==='string').map(r=>metadata({...r,id:r.id||'import:'+String(r.title||r['track name'])+'|'+String(r.artist||r['artist name']),title:r.title||r['track name'],artist:r.artist||r['artist name']})).filter(r=>r.title&&r.artist);imported=[...new Map([...imported,...normalized].map(r=>[key(r),r])).values()].slice(0,500);localStorage.setItem('oktawka-imports',JSON.stringify(imported));renderHome();$('#import-summary').textContent=imported.length+' unique tracks imported. Find the playlist in Made from your rotation.'}catch(error){if($('#import-summary'))$('#import-summary').textContent=error.message}e.target.value=''};
$('#import-library').onclick=importDialog;$('#flow-options').onclick=options;
function category(name){version++;$('#home-main').hidden=name!=='home';$('#radio-category').hidden=name!=='radio';$('#open-category').hidden=name!=='open';$('#page-title').textContent=name==='radio'?'A station for your state of mind.':name==='open'?'A world of independent sound.':'Your collection, your way.';document.querySelectorAll('[data-category]').forEach(b=>b.classList.toggle('active',b.dataset.category===name))}
document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>category(b.dataset.category));document.querySelectorAll('[data-view]').forEach(b=>{const original=b.onclick;b.onclick=()=>{category('home');original?.()}});$('#search').addEventListener('input',()=>category('home'));
window.OktawkaFlow={snapshot:()=>({items:queue.slice(),position}),playAlbum,ended,next:nextInQueue,remember,cancel:()=>{version++;queue=[];position=-1},csv};renderHome();
})();
